warp:
shader_body
{
vec2 _uv = uv;

    // sample previous frame
    ret.xyz = texture( sampler_main, _uv ).xyz;

      // take the difference between the crisp and blurred images,
      // then add it back into the image.  Creates spots and stripes over time.
      ret.xyz += (ret.xyz - ((texture(sampler_blur2, _uv).xyz * scale2) + bias2))*0.3;
      ret.xyz *= 0.9;

      // add noise:
      vec2 dither_uv = uv_orig*texsize.xy*texsize_noise_lq.zw * 0.4 + rand_frame.xy;
      ret.xyz += (texture(sampler_noise_lq, dither_uv).xyz-0.5)/256.0 * 122.0 * clamp(treb_att-1.0, 0.0, 1.0);

      // desaturate over time, to keep the globs white
      ret.xyz = mix(ret.xyz, lum(ret.xyz), 0.2);

}

comp:
vec2 d, uv_y;
vec3 dx, dy;
shader_body
{

    d = texsize.zw*8.0;
    dx = ( ((texture(sampler_blur1, uv+vec2(1.0,0.0)*d).xyz * scale1) + bias1)-((texture(sampler_blur1, uv-vec2(1.0,0.0)*d).xyz * scale1) + bias1) );
    dy = ( ((texture(sampler_blur1, uv+vec2(0.0,1.0)*d).xyz * scale1) + bias1)-((texture(sampler_blur1, uv-vec2(0.0,1.0)*d).xyz * scale1) + bias1) );

vec3 base = texture(sampler_main, uv).xyz;
vec3 emboss = (-dx + dy + 1.0)*1.2;

    d = texsize.zw*2.0;
    dx = ( ((texture(sampler_blur1, uv+vec2(1.0,0.0)*d).xyz * scale1) + bias1)-((texture(sampler_blur1, uv-vec2(1.0,0.0)*d).xyz * scale1) + bias1) );
    dy = ( ((texture(sampler_blur1, uv+vec2(0.0,1.0)*d).xyz * scale1) + bias1)-((texture(sampler_blur1, uv-vec2(0.0,1.0)*d).xyz * scale1) + bias1) );

float grad = length(vec2(dx.x,dy.x));

ret = mix( vec3(0.5,0.4,0.6)*base.x*emboss.x,
            vec3(8.0,5.0,2.0)*grad,
            grad*4.2
          ); 
ret = mix(ret,4.0*ret,texture(sampler_main, uv).xyz.y*0.5-((texture(sampler_blur1, uv).xyz * scale1) + bias1).z*0.3*vec3(0.3,1.0,1.0));

grad = length(vec2(dx.z,dy.z));
ret = mix(ret, vec3(2.0,2.0,0.0), grad*0.7);
}
